import test from 'node:test';
import assert from 'node:assert/strict';
import { normalizeTitle } from '../src/index.js';

test('normalizes whitespace', () => {
  assert.equal(normalizeTitle('  Example   change  '), 'Example change');
});
test('rejects short titles', () => {
  assert.throws(() => normalizeTitle('x'), /at least 3 characters/);
});
